from lib import *
S = SS('j282')
steps = [
    step("过滤器的执行顺序(Jersey 3.1.9 + JDK 内置 HTTP 服务器,GET /hello;过滤器的注册顺序是任意的,执行顺序由 @Priority 决定):请求过滤器按优先级从小到大:PreMatching A(100)、PreMatching B(200)(@PreMatching 都排在匹配之前)、Post First(100)、Post A(300)、Post Last(400),然后才是资源方法 hello()。响应过滤器按优先级从大到小:Resp(300)、Resp(100)(此时能看到响应实体 hello)、TraceEmit(10) 最后。请求链是升序,响应链是降序。", t=tl(S(1)), done=lidx(S(1), 'PreMatching A(100)', 'PreMatching B(200)', 'Post First(100)'), mark=lidx(S(1), 'Post A(300)', 'Post Last(400)', '资源:hello() 被调用', '响应:Resp(300)', '响应:Resp(100)', 'TraceEmit(10)'), kv=KV([['请求过滤器', '@Priority 升序:100 → 200 → 300 → 400'], ['响应过滤器', '@Priority 降序:300 → 100 → 10'], ['@PreMatching', '先于资源匹配']], ['响应过滤器'])),
    step("@PreMatching 能改写请求:GET /legacy/hello 被 PreMatching A 改写成 hello,之后 Post 过滤器看到匹配到的资源方法 hello,资源正常执行;POST /echo 带 X-Method-Override 被 PreMatching B 改成 PUT,匹配到 put() 而不是 post(),响应体 put:abc。GET /nope(没有匹配的资源)→ 404:两个 PreMatching 过滤器与响应过滤器运行了,Post 过滤器与资源没有运行。", t=tl(S(2)), done=lidx(S(2), 'GET /legacy/hello', 'PreMatching A 把 legacy/hello 改写成 hello'), mark=lidx(S(2), 'POST /echo + X-Method-Override', 'PreMatching B 把 POST 改成 PUT', 'GET /nope', '资源:put() 被调用'), kv=KV([['PreMatching 改写路径 / 方法', '匹配到改写后的资源方法'], ['404(无匹配)', 'PreMatching 与响应过滤器运行,Post 过滤器不运行']], ['404(无匹配)'])),
    step("abortWith 与异常:Post First 调用 abortWith(403):Post A、Post Last 与资源都被跳过,响应过滤器仍然运行(状态 403,响应体“被过滤器拒绝”)。请求过滤器 Post Last 抛出 IllegalStateException:被 ExceptionMapper 映射成 500(响应体“映射后的异常:请求过滤器抛出”),响应过滤器看到的状态是 500。资源 boom() 抛出的异常同样被映射成 500,响应过滤器同样运行。过滤器里的异常与资源里的异常走同一条 ExceptionMapper 路径。", t=tl(S(3)), done=lidx(S(3), 'GET /hello + X-Mode: deny', 'Post First 调用 abortWith(403)'), mark=lidx(S(3), 'X-Mode: throw', 'Post Last 抛出 IllegalStateException', 'GET /boom', '资源:boom() 抛出'), kv=KV([['abortWith(403)', '跳过后面的请求过滤器与资源,响应过滤器照常运行'], ['过滤器 / 资源抛出异常', '都由 ExceptionMapper 映射,响应过滤器照常运行']], ['abortWith(403)'])),
    step("名字绑定与请求体:带 @Audited 的方法 /audited 会运行名字绑定的 Audit 过滤器(Post Last(400) 之后、优先级 500),没有 @Audited 的 /hello 不运行。请求过滤器读取请求体要小心:BodyPeek 读取了 11 字节但没有放回,资源 put() 收到的 body 长度是 0(响应体 put:);读取后用 setEntityStream(new ByteArrayInputStream(bytes)) 放回,资源收到完整的 payload-123(长度 11)。", t=tl(S(4)), done=lidx(S(4), 'GET /audited', '请求:Audit 过滤器', 'GET /hello(没有 @Audited'), mark=lidx(S(4), '过滤器读取了请求体但没放回', 'BodyPeek 读取了请求体 11 字节', 'body 长度 0', '过滤器读取后又把字节放回', 'body 长度 11'), kv=KV([['@Audited(名字绑定)', '只对标注的方法运行过滤器'], ['过滤器读了请求体没放回', '资源收到空 body(长度 0)'], ['setEntityStream 放回', '资源收到完整 body(长度 11)']], ['过滤器读了请求体没放回'])),
]
A = mkartj('j282', 282, 'Java,JAX-RS,Jersey,过滤器,ContainerRequestFilter,ExceptionMapper,真实验证,动画演示',
    '用 Jersey 3.1.9 + JDK HTTP 服务器实测 JAX-RS 过滤器:请求过滤器按 @Priority 升序、响应过滤器降序;@PreMatching 能改写路径与方法;abortWith 跳过资源但响应过滤器照常运行;过滤器抛出的异常经 ExceptionMapper 映射成 500;过滤器读取请求体不放回会让资源收到空 body。',
    'JAX-RS 过滤器是在 HTTP 资源前后插入处理的标准方式。这篇用一个真实的 Jersey 服务,把请求与响应链的顺序、PreMatching、abortWith、异常映射、名字绑定和请求体读取这些容易混淆的行为逐个量出来。',
    [('升序 vs 降序', '请求过滤器与响应过滤器按 @Priority 的执行顺序(100 → 400 与 300 → 100 → 10)'), ('403 / 500', 'abortWith 与过滤器抛异常的 HTTP 状态;两种情况响应过滤器都照常运行'), ('0 字节', '请求过滤器读取了请求体但没放回时,资源方法收到的 body 长度(放回之后是 11)')],
    [('执行顺序', None), ('PreMatching', None), ('abortWith 与异常', None), ('名字绑定与请求体', None)],
    steps, [ENV_J + '。Jersey 3.1.9(jersey-container-jdk-http + jersey-hk2)、Jakarta RESTful Web Services 3.1,服务端是 JDK 内置的 com.sun.net.httpserver(端口 9780);每个请求的执行轨迹由过滤器写进请求属性并通过 X-Trace-Utf8 响应头带回客户端', '没有验证:RESTEasy / CXF 等其它实现的差异、DynamicFeature 动态绑定、ReaderInterceptor / WriterInterceptor 与过滤器的先后、异步响应(@Suspended)下的过滤器、Servlet 容器(Tomcat / Jetty)中的 Servlet Filter 与 JAX-RS 过滤器的顺序、CORS 过滤器的实现'], 'JAX-RS 过滤器')
